// Mensajes que recibe el bot de la plataforma. Telegram manda en cada llamada
// el secreto que se le dio en setWebhook (header X-Telegram-Bot-Api-Secret-Token):
// sin él, cualquiera podría mandar "/start <código>" haciéndose pasar por
// Telegram y vincular su chat a un espacio ajeno. Sin secreto configurado se
// falla cerrado.
const leerEnv = (clave) => {
  try { return (typeof $env !== 'undefined' && $env) ? String($env[clave] || '') : ''; } catch (e) { return ''; }
};
const secreto = leerEnv('TELEGRAM_WEBHOOK_SECRET');
const e = $input.first().json || {};
const recibido = (e.headers || {})['x-telegram-bot-api-secret-token'] || '';
if (!secreto || recibido !== secreto) return [];
const msg = (e.body || {}).message || {};
const chatId = msg.chat && msg.chat.id;
if (!chatId) return [];
// El enlace del panel abre el bot con "/start <código>"; también se acepta el
// código solo, por si lo copian a mano.
const texto = String(msg.text || '').trim();
const m = texto.match(/^(?:\/start\s+)?([A-Za-z0-9]{8})$/);
return [{ json: { chat_id: String(chatId), codigo: m ? m[1].toUpperCase() : '' } }];
